// Reads one pf_ Slack interaction (parsed by UXR Interaction Handler) and decides what to do.
// It only calls run addresses on this n8n instance under /webhook-waiting/. Anything else is ignored.
const p = $('When Called By UXR Handler').first().json;
const ownHost = (String($execution.resumeUrl).match(/^https?:\/\/([^/]+)/) || [])[1] || '';
// Plain text check (the URL class is not available in the Code node sandbox).
const isOurs = (u) => {
  const m = String(u ?? '').match(/^https:\/\/([^/?#]+)(\/[^?#]*)/);
  return !!m && ownHost !== '' && m[1] === ownHost && m[2].startsWith('/webhook-waiting/');
};
const ignore = (reason) => [{ json: { op: 'ignore', reason, action_id: p.action_id ?? null, own_host: ownHost } }];
const id = String(p.action_id || '');
const type = String(p.action_type || '');

// Yes / No / $50 / No reward / Confirm / Cancel: the button value is the run address with the answer.
if (type === 'block_actions' && id.startsWith('pf_answer_')) {
  const url = String(p.action_value || '');
  return isOurs(url) ? [{ json: { op: 'resume', url } }] : ignore('answer address is not on this instance');
}

// Other amount: open the modal first (trigger_id is valid for 3 seconds), then move the run on.
if (type === 'block_actions' && id === 'pf_amount_open') {
  let v = {};
  try { v = JSON.parse(String(p.action_value || '{}')); } catch (e) { v = {}; }
  if (![v.c, v.a, v.f].every(isOurs)) return ignore('amount addresses are not on this instance');
  const max = Number(v.max) || 100;
  const view = {
    type: 'modal',
    callback_id: 'pf_amount_submit',
    private_metadata: JSON.stringify({ a: v.a, channel_id: p.channel_id, message_ts: p.message_ts }),
    title: { type: 'plain_text', text: 'Reward amount' },
    submit: { type: 'plain_text', text: 'Continue' },
    close: { type: 'plain_text', text: 'Cancel' },
    blocks: [{
      type: 'input',
      block_id: 'amount_block',
      label: { type: 'plain_text', text: `Amount in USD (whole dollars, 1 to ${max})` },
      element: {
        type: 'number_input', action_id: 'amount_input', is_decimal_allowed: false,
        min_value: '1', max_value: String(max), placeholder: { type: 'plain_text', text: 'e.g. 75' },
      },
    }],
  };
  return [{ json: { op: 'open_modal', trigger_id: p.trigger_id, view, choice_url: v.c, fallback_url: v.f } }];
}

// Modal submit: send the amount to the waiting run (Wait For Modal Amount in PF Reward).
if (type === 'view_submission' && id === 'pf_amount_submit') {
  const view = p.full_payload?.view ?? {};
  let meta = {};
  try { meta = JSON.parse(view.private_metadata || '{}'); } catch (e) { meta = {}; }
  const amount = view.state?.values?.amount_block?.amount_input?.value ?? '';
  if (!isOurs(meta.a)) return ignore('amount address is not on this instance');
  return [{ json: { op: 'resume', url: `${meta.a}&amount=${encodeURIComponent(amount)}` } }];
}

return ignore(`unknown pf_ action ${id}`);
